// AUTO-GENERATED handbook document embedded for the admin-only Handbook tab.
// Rendered inside an isolated <iframe srcDoc> so its styles never leak into the
// class portal. This is the HR Portal Handbook; edit here to update the copy.
/* eslint-disable */
export const HANDBOOK_HTML: string = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Aura Health Rehab — HR Portal Handbook</title>\n<style>\n  :root{\n    --ink:#16302E; --body:#31403D; --muted:#6A7B78;\n    --teal:#157A72; --teal-deep:#0E4A46; --teal-soft:#E4EFEC;\n    --line:#D6E2DE; --line-soft:#E8F0ED;\n    --paper:#F3F6F4; --card:#FFFFFF;\n    /* role accents (semantic, distinct from brand teal) */\n    --mgr:#7E4CC4; --mgr-bg:#F1EAFB;\n    --hr:#1F6FB2;  --hr-bg:#E7F0F9;\n    --stf:#2E8B57; --stf-bg:#E6F3EC;\n    --warn:#B7791F; --warn-bg:#FBF4E4;\n    --sans:system-ui,-apple-system,\"Segoe UI\",Roboto,Helvetica,Arial,sans-serif;\n    --mono:ui-monospace,\"SF Mono\",Menlo,Consolas,monospace;\n    --measure:70ch;\n  }\n  *{box-sizing:border-box;}\n  body{margin:0;background:var(--paper);color:var(--body);\n    font-family:var(--sans);font-size:16px;line-height:1.62;\n    -webkit-font-smoothing:antialiased;}\n  a{color:var(--teal);text-underline-offset:2px;}\n  h1,h2,h3,h4{color:var(--ink);text-wrap:balance;line-height:1.2;margin:0;}\n  code{font-family:var(--mono);font-size:.86em;background:var(--teal-soft);\n    color:var(--teal-deep);padding:.08em .4em;border-radius:4px;\n    white-space:nowrap;}\n\n  /* ── Shell ─────────────────────────────────────── */\n  .wrap{max-width:1160px;margin:0 auto;padding:0 24px;}\n  .shell{display:grid;grid-template-columns:236px minmax(0,1fr);\n    gap:52px;align-items:start;}\n  @media(max-width:860px){.shell{grid-template-columns:1fr;gap:0;}}\n\n  /* ── Masthead ─────────────────────────────────── */\n  header.mast{background:\n      radial-gradient(120% 140% at 100% 0%, rgba(21,122,114,.14), transparent 60%),\n      linear-gradient(180deg,#0E4A46,#12645C);\n    color:#DCEBE8;padding:52px 0 46px;}\n  .mast .wrap{display:flex;flex-direction:column;gap:18px;}\n  .kicker{font-family:var(--mono);font-size:12.5px;letter-spacing:.22em;\n    text-transform:uppercase;color:#7FC3B9;}\n  .mast h1{color:#FFFFFF;font-size:clamp(30px,4.6vw,46px);font-weight:800;\n    letter-spacing:-.02em;max-width:20ch;}\n  .mast p.lede{margin:0;max-width:60ch;color:#CDE3DE;font-size:17px;}\n  .mast .meta{display:flex;flex-wrap:wrap;gap:10px 22px;margin-top:6px;\n    font-size:13.5px;color:#A9D0C9;}\n  .mast .meta b{color:#EAF5F2;font-weight:600;}\n  .mast .meta code{background:rgba(255,255,255,.12);color:#EAF5F2;}\n\n  /* ── Body layout ──────────────────────────────── */\n  main{padding:44px 0 90px;}\n\n  /* Sticky TOC */\n  nav.toc{position:sticky;top:20px;font-size:13.5px;}\n  @media(max-width:860px){nav.toc{position:static;margin-bottom:28px;\n    border:1px solid var(--line);border-radius:12px;background:var(--card);\n    padding:14px 16px;}}\n  nav.toc .toc-h{font-family:var(--mono);font-size:11px;letter-spacing:.18em;\n    text-transform:uppercase;color:var(--muted);margin:0 0 10px;}\n  nav.toc ol{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:1px;}\n  nav.toc a{display:block;padding:5px 10px;border-radius:7px;color:var(--body);\n    text-decoration:none;border-left:2px solid transparent;transition:background .15s,color .15s;}\n  nav.toc a:hover{background:var(--teal-soft);color:var(--teal-deep);}\n  nav.toc a.sub{padding-left:20px;font-size:12.5px;color:var(--muted);}\n  nav.toc a:focus-visible{outline:2px solid var(--teal);outline-offset:1px;}\n\n  /* Sections */\n  section{margin-bottom:52px;scroll-margin-top:20px;}\n  .eyebrow{font-family:var(--mono);font-size:12px;letter-spacing:.16em;\n    text-transform:uppercase;color:var(--teal);margin-bottom:8px;}\n  section > h2{font-size:26px;font-weight:800;letter-spacing:-.015em;\n    padding-bottom:12px;border-bottom:2px solid var(--line);margin-bottom:20px;}\n  section p{max-width:var(--measure);}\n  h3.blockh{font-size:18px;font-weight:700;margin:26px 0 8px;}\n\n  /* Role legend / badges */\n  .badge{display:inline-flex;align-items:center;gap:6px;font-size:12px;\n    font-weight:600;padding:3px 9px 3px 7px;border-radius:999px;\n    line-height:1;white-space:nowrap;}\n  .badge .dot{width:14px;height:14px;border-radius:50%;color:#fff;\n    font-size:9px;font-weight:800;display:grid;place-items:center;}\n  .b-mgr{background:var(--mgr-bg);color:#5B2E96;}   .b-mgr .dot{background:var(--mgr);}\n  .b-hr{background:var(--hr-bg);color:#154C7E;}      .b-hr .dot{background:var(--hr);}\n  .b-stf{background:var(--stf-bg);color:#1F6340;}    .b-stf .dot{background:var(--stf);}\n\n  .legend{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:22px 0 8px;}\n  @media(max-width:620px){.legend{grid-template-columns:1fr;}}\n  .legend .rc{background:var(--card);border:1px solid var(--line);border-radius:12px;\n    padding:16px 16px 15px;border-top:3px solid var(--rc);}\n  .legend .rc.mgr{--rc:var(--mgr);} .legend .rc.hr{--rc:var(--hr);} .legend .rc.stf{--rc:var(--stf);}\n  .legend .rc h4{font-size:15.5px;margin-bottom:2px;display:flex;align-items:center;gap:8px;}\n  .legend .rc .who{font-family:var(--mono);font-size:11.5px;color:var(--muted);\n    margin-bottom:9px;}\n  .legend .rc p{font-size:13.5px;margin:0;color:var(--body);}\n\n  /* Cards */\n  .cards{display:flex;flex-direction:column;gap:16px;}\n  .mod{background:var(--card);border:1px solid var(--line);border-radius:14px;\n    padding:20px 22px;}\n  .mod-top{display:flex;flex-wrap:wrap;align-items:baseline;gap:8px 12px;margin-bottom:4px;}\n  .mod-top h3{font-size:17.5px;font-weight:750;}\n  .mod-top .loc{font-family:var(--mono);font-size:12px;color:var(--muted);}\n  .mod-roles{display:flex;flex-wrap:wrap;gap:6px;margin:10px 0 12px;}\n  .mod .desc{max-width:var(--measure);margin:0 0 4px;}\n  .mod ul{margin:8px 0 0;padding-left:0;list-style:none;max-width:var(--measure);\n    display:flex;flex-direction:column;gap:7px;}\n  .mod ul li{position:relative;padding-left:22px;font-size:14.5px;}\n  .mod ul li::before{content:\"\";position:absolute;left:4px;top:9px;width:6px;height:6px;\n    border-radius:50%;background:var(--teal);}\n  .mod .note{margin-top:12px;font-size:13.5px;background:var(--teal-soft);\n    border-radius:9px;padding:10px 13px;color:var(--teal-deep);max-width:var(--measure);}\n  .mod .note b{color:var(--teal-deep);}\n\n  .grouphead{font-size:13px;font-family:var(--mono);letter-spacing:.12em;\n    text-transform:uppercase;color:var(--muted);margin:30px 0 12px;\n    display:flex;align-items:center;gap:12px;}\n  .grouphead::after{content:\"\";flex:1;height:1px;background:var(--line);}\n\n  /* Callouts */\n  .call{border-radius:12px;padding:15px 18px;margin:18px 0;max-width:var(--measure);\n    font-size:14.5px;border:1px solid var(--line-soft);}\n  .call b{color:var(--ink);}\n  .call.rule{background:var(--warn-bg);border-color:#EAD9AE;}\n  .call.rule .lbl{color:var(--warn);}\n  .call.tip{background:var(--teal-soft);border-color:#BFDBD5;}\n  .call.tip .lbl{color:var(--teal-deep);}\n  .call .lbl{font-family:var(--mono);font-size:11px;letter-spacing:.14em;\n    text-transform:uppercase;display:block;margin-bottom:5px;font-weight:700;}\n\n  /* Playbook steps */\n  .play{background:var(--card);border:1px solid var(--line);border-radius:14px;\n    padding:20px 22px;margin-bottom:16px;border-left:4px solid var(--pc);}\n  .play.mgr{--pc:var(--mgr);} .play.hr{--pc:var(--hr);} .play.stf{--pc:var(--stf);}\n  .play h3{font-size:16.5px;display:flex;align-items:center;gap:9px;margin-bottom:12px;}\n  .play ol{margin:0;padding-left:0;counter-reset:s;list-style:none;\n    display:flex;flex-direction:column;gap:9px;max-width:var(--measure);}\n  .play ol li{position:relative;padding-left:34px;counter-increment:s;font-size:14.5px;}\n  .play ol li::before{content:counter(s);position:absolute;left:0;top:-1px;\n    width:22px;height:22px;border-radius:50%;background:var(--pc);color:#fff;\n    font-size:12px;font-weight:700;display:grid;place-items:center;\n    font-variant-numeric:tabular-nums;}\n\n  /* Quick access table */\n  .tablewrap{overflow-x:auto;border:1px solid var(--line);border-radius:12px;margin-top:8px;}\n  table{border-collapse:collapse;width:100%;font-size:13.5px;min-width:520px;}\n  th,td{text-align:left;padding:10px 14px;border-bottom:1px solid var(--line-soft);}\n  thead th{background:var(--teal-soft);color:var(--teal-deep);font-size:11.5px;\n    letter-spacing:.06em;text-transform:uppercase;position:sticky;top:0;}\n  tbody tr:last-child td{border-bottom:none;}\n  td.mod-name{font-weight:600;color:var(--ink);}\n  .yes{color:var(--stf);font-weight:700;}\n  .part{color:var(--warn);font-weight:600;font-size:12.5px;}\n  .no{color:#C0CBC8;}\n\n  footer{border-top:1px solid var(--line);padding:26px 0 40px;color:var(--muted);\n    font-size:13px;}\n  footer .wrap{display:flex;flex-wrap:wrap;justify-content:space-between;gap:12px;}\n\n  @media(prefers-reduced-motion:reduce){*{transition:none!important;}}\n  @media print{\n    body{background:#fff;font-size:11.5pt;}\n    header.mast{background:#0E4A46!important;-webkit-print-color-adjust:exact;print-color-adjust:exact;}\n    nav.toc{display:none;} .shell{grid-template-columns:1fr;}\n    .mod,.play,.legend .rc{break-inside:avoid;}\n    section{margin-bottom:26px;}\n  }\n</style>\n</head>\n<body>\n<header class=\"mast\">\n  <div class=\"wrap\">\n    <span class=\"kicker\">Human Resources Portal · User Handbook</span>\n    <h1>How to Use the Aura Health Rehab HR Portal</h1>\n    <p class=\"lede\">One system for staff records, hiring, trainings, invoices, meetings, and compliance —\n      built so a clinic manager, an HR officer, and every staff member each see exactly what they need.\n      This handbook walks through each part of the portal and the everyday tasks for your role.</p>\n    <div class=\"meta\">\n      <span>Address: <code>hr.sapphireclinicseast.org</code></span>\n      <span>Sign in with your <b>work email &amp; password</b></span>\n      <span>Audience: <b>Managers · HR Officers · Staff</b></span>\n    </div>\n  </div>\n</header>\n\n<main class=\"wrap\">\n<div class=\"shell\">\n\n  <!-- ── TOC ── -->\n  <nav class=\"toc\" aria-label=\"Contents\">\n    <p class=\"toc-h\">Contents</p>\n    <ol>\n      <li><a href=\"#start\">1 · Getting started</a></li>\n      <li><a href=\"#roles\">2 · Know your role</a></li>\n      <li><a href=\"#access\" class=\"sub\">Who sees what</a></li>\n      <li><a href=\"#modules\">3 · The modules</a></li>\n      <li><a href=\"#g-people\" class=\"sub\">People &amp; records</a></li>\n      <li><a href=\"#g-grow\" class=\"sub\">Hiring &amp; development</a></li>\n      <li><a href=\"#g-ops\" class=\"sub\">Everyday operations</a></li>\n      <li><a href=\"#g-care\" class=\"sub\">Patient care &amp; quality</a></li>\n      <li><a href=\"#g-gov\" class=\"sub\">Compliance &amp; governance</a></li>\n      <li><a href=\"#play\">4 · Role playbooks</a></li>\n      <li><a href=\"#rules\">5 · Golden rules</a></li>\n    </ol>\n  </nav>\n\n  <div class=\"content\">\n\n    <!-- ════ 1 · GETTING STARTED ════ -->\n    <section id=\"start\">\n      <p class=\"eyebrow\">Section 1</p>\n      <h2>Getting started</h2>\n      <p>The portal lives at <code>hr.sapphireclinicseast.org</code>. Open it in any browser,\n        sign in with your work email and password, and you land on your home screen. What you see\n        is decided entirely by your <b>role</b> — nobody has to hide anything manually.</p>\n\n      <h3 class=\"blockh\">The three things on every screen</h3>\n      <div class=\"mod\">\n        <ul>\n          <li><b>The sidebar (left)</b> is your menu of modules. It only lists the tools your role\n            is allowed to open, so a shorter list simply means a more focused role — nothing is missing.</li>\n          <li><b>The notification bell (top-right)</b> flags new items that need a person's attention —\n            a new staff concern, a patient complaint, a fresh form response, or a service-invoice deadline.\n            New entries are highlighted; clicking a notification jumps you straight to it.</li>\n          <li><b>Your account menu (top-right)</b> shows who you're signed in as and your branch, and is\n            where you sign out.</li>\n        </ul>\n      </div>\n\n      <div class=\"call tip\">\n        <span class=\"lbl\">Branch scoping</span>\n        Managers see <b>all branches</b>. An HR officer is tied to <b>one branch</b> (East, Greenhills,\n        or Verdana) and only ever sees that branch's people and data — even for a consultant who works at\n        two branches, an officer sees only their own branch's half. This is enforced by the system, not by trust.\n      </div>\n    </section>\n\n    <!-- ════ 2 · ROLES ════ -->\n    <section id=\"roles\">\n      <p class=\"eyebrow\">Section 2</p>\n      <h2>Know your role</h2>\n      <p>This handbook is written for the three roles that use the portal day to day. Throughout, each\n        module is tagged with the roles that can open it, using these badges:</p>\n\n      <div class=\"legend\">\n        <div class=\"rc mgr\">\n          <h4><span class=\"badge b-mgr\"><span class=\"dot\">M</span> Clinic Manager</span></h4>\n          <div class=\"who\">system role: admin</div>\n          <p>The main administrator. Sees and manages <b>everything, across every branch</b> — people,\n            money, hiring, governance. The only role that can manage user accounts and view shareholder records.</p>\n        </div>\n        <div class=\"rc hr\">\n          <h4><span class=\"badge b-hr\"><span class=\"dot\">H</span> HR Officer</span></h4>\n          <div class=\"who\">system role: branch admin</div>\n          <p>Runs HR for <b>one branch</b>. Full use of the day-to-day tools — staff records, hiring,\n            trainings, invoices, concerns — but limited to their own branch's data.</p>\n        </div>\n        <div class=\"rc stf\">\n          <h4><span class=\"badge b-stf\"><span class=\"dot\">S</span> Regular Staff</span></h4>\n          <div class=\"who\">system role: staff / probationary</div>\n          <p>An employee or consultant. Sees <b>their own</b> profile, the trainings and meetings they're\n            invited to, their weekly reports and peer evaluations, and the manuals.</p>\n        </div>\n      </div>\n\n      <p style=\"margin-top:20px;font-size:14px;color:var(--muted);max-width:var(--measure);\">\n        Two other roles exist for special cases: a <b>Director</b> (board member — sees only Shareholders,\n        Document Hub, and the Staff Dashboard) and a <b>Marketing Admin</b> (Staff Profiles, Trainings, and\n        Patient CRM only). They're mentioned where relevant but aren't the focus here.</p>\n\n      <h3 class=\"blockh\" id=\"access\">Who sees what — at a glance</h3>\n      <div class=\"tablewrap\">\n        <table>\n          <thead><tr><th>Module</th><th>Manager</th><th>HR&nbsp;Officer</th><th>Staff</th></tr></thead>\n          <tbody>\n            <tr><td class=\"mod-name\">Dashboard</td><td class=\"yes\">✓</td><td class=\"yes\">✓</td><td class=\"no\">—</td></tr>\n            <tr><td class=\"mod-name\">Staff Profiles</td><td class=\"yes\">✓ all</td><td class=\"part\">✓ own branch</td><td class=\"part\">own profile</td></tr>\n            <tr><td class=\"mod-name\">Staff Dashboard</td><td class=\"yes\">✓</td><td class=\"yes\">✓</td><td class=\"no\">—</td></tr>\n            <tr><td class=\"mod-name\">Accounts &amp; Access</td><td class=\"yes\">✓</td><td class=\"no\">—</td><td class=\"no\">—</td></tr>\n            <tr><td class=\"mod-name\">Hiring</td><td class=\"yes\">✓</td><td class=\"yes\">✓</td><td class=\"no\">—</td></tr>\n            <tr><td class=\"mod-name\">Seminars &amp; Training</td><td class=\"yes\">✓</td><td class=\"yes\">✓</td><td class=\"part\">invited</td></tr>\n            <tr><td class=\"mod-name\">Peer Evaluation</td><td class=\"yes\">✓</td><td class=\"yes\">✓</td><td class=\"yes\">✓</td></tr>\n            <tr><td class=\"mod-name\">Manuals</td><td class=\"yes\">✓</td><td class=\"yes\">✓</td><td class=\"yes\">✓</td></tr>\n            <tr><td class=\"mod-name\">Templates</td><td class=\"yes\">✓</td><td class=\"yes\">✓</td><td class=\"no\">—</td></tr>\n            <tr><td class=\"mod-name\">Meetings</td><td class=\"yes\">✓</td><td class=\"yes\">✓</td><td class=\"part\">invited</td></tr>\n            <tr><td class=\"mod-name\">Task Checklist</td><td class=\"yes\">✓</td><td class=\"yes\">✓</td><td class=\"no\">—</td></tr>\n            <tr><td class=\"mod-name\">Weekly Accomplishment</td><td class=\"yes\">✓</td><td class=\"yes\">✓</td><td class=\"yes\">✓</td></tr>\n            <tr><td class=\"mod-name\">Service Invoices</td><td class=\"yes\">✓</td><td class=\"yes\">✓</td><td class=\"part\">own</td></tr>\n            <tr><td class=\"mod-name\">Forms</td><td class=\"yes\">✓</td><td class=\"yes\">✓</td><td class=\"no\">—</td></tr>\n            <tr><td class=\"mod-name\">Patient CRM</td><td class=\"yes\">✓</td><td class=\"yes\">✓</td><td class=\"no\">—</td></tr>\n            <tr><td class=\"mod-name\">Customer Survey</td><td class=\"yes\">✓</td><td class=\"yes\">✓</td><td class=\"no\">—</td></tr>\n            <tr><td class=\"mod-name\">Patient Complaints</td><td class=\"yes\">✓</td><td class=\"yes\">✓</td><td class=\"no\">—</td></tr>\n            <tr><td class=\"mod-name\">Staff Concerns</td><td class=\"yes\">✓</td><td class=\"yes\">✓</td><td class=\"no\">—</td></tr>\n            <tr><td class=\"mod-name\">Government Submissions</td><td class=\"yes\">✓</td><td class=\"yes\">✓</td><td class=\"no\">—</td></tr>\n            <tr><td class=\"mod-name\">Document Hub</td><td class=\"yes\">✓</td><td class=\"yes\">✓</td><td class=\"no\">—</td></tr>\n            <tr><td class=\"mod-name\">KPI Monitoring</td><td class=\"yes\">✓</td><td class=\"yes\">✓</td><td class=\"no\">—</td></tr>\n            <tr><td class=\"mod-name\">Shareholders</td><td class=\"yes\">✓</td><td class=\"no\">—</td><td class=\"no\">—</td></tr>\n          </tbody>\n        </table>\n      </div>\n    </section>\n\n    <!-- ════ 3 · MODULES ════ -->\n    <section id=\"modules\">\n      <p class=\"eyebrow\">Section 3</p>\n      <h2>The modules</h2>\n      <p>Each tool in the sidebar is a module. They're grouped below by what they help you do. Every card\n        shows who can open it and how to use it.</p>\n\n      <!-- People & records -->\n      <div class=\"grouphead\" id=\"g-people\">People &amp; records</div>\n      <div class=\"cards\">\n\n        <div class=\"mod\">\n          <div class=\"mod-top\"><h3>Staff Profiles</h3><span class=\"loc\">sidebar › Staff Profiles</span></div>\n          <div class=\"mod-roles\">\n            <span class=\"badge b-mgr\"><span class=\"dot\">M</span> all branches</span>\n            <span class=\"badge b-hr\"><span class=\"dot\">H</span> own branch</span>\n            <span class=\"badge b-stf\"><span class=\"dot\">S</span> own profile</span>\n          </div>\n          <p class=\"desc\">The master record for every employee and consultant: personal details, government\n            IDs, bank details, employment details (department, title, rates, dates), a profile photo, and\n            uploaded 201-file documents.</p>\n          <ul>\n            <li><b>Add someone:</b> click <b>New Staff</b>, fill the tabs, tick which branch(es) they work at,\n              and complete the Employment Details for each ticked branch.</li>\n            <li><b>Edit someone:</b> open their card, click <b>Edit</b>, change the fields, and Save.</li>\n            <li><b>Profile photo:</b> click <b>Upload Photo</b>, then <b>Adjust / Zoom</b> to drag and zoom so\n              the face sits nicely in the round avatar before saving.</li>\n            <li><b>201 files:</b> upload documents per branch under the person's file section.</li>\n          </ul>\n          <div class=\"note\"><b>Interbranch consultants:</b> a person can work at more than one branch with\n            different Employment Details at each. A Manager sees and edits both; an HR officer sees and edits\n            <b>only their own branch's half</b> — the other branch is hidden and cannot be changed.</div>\n        </div>\n\n        <div class=\"mod\">\n          <div class=\"mod-top\"><h3>Staff Dashboard</h3><span class=\"loc\">sidebar › Staff Dashboard</span></div>\n          <div class=\"mod-roles\">\n            <span class=\"badge b-mgr\"><span class=\"dot\">M</span></span>\n            <span class=\"badge b-hr\"><span class=\"dot\">H</span></span>\n          </div>\n          <p class=\"desc\">The analytics view over your workforce — headcounts, employment types, department\n            and specialization breakdowns, top schools, and rate analytics. Use it to answer \"how many, where,\n            and what kind\" without opening individual profiles.</p>\n        </div>\n\n        <div class=\"mod\">\n          <div class=\"mod-top\"><h3>Accounts &amp; Access</h3><span class=\"loc\">sidebar › Access</span></div>\n          <div class=\"mod-roles\"><span class=\"badge b-mgr\"><span class=\"dot\">M</span> Manager only</span></div>\n          <p class=\"desc\">Where user logins are created and roles are assigned. This is how a person becomes an\n            HR officer, a staff member, or a director, and how you link a login to a staff profile.</p>\n          <ul>\n            <li>Create an account with a name, email, temporary password, and role.</li>\n            <li>Assign the branch-specific admin role to give an HR officer their branch.</li>\n            <li>Because this controls who sees what, it is reserved for the Manager.</li>\n          </ul>\n        </div>\n      </div>\n\n      <!-- Hiring & development -->\n      <div class=\"grouphead\" id=\"g-grow\">Hiring &amp; development</div>\n      <div class=\"cards\">\n\n        <div class=\"mod\">\n          <div class=\"mod-top\"><h3>Hiring</h3><span class=\"loc\">sidebar › Hiring</span></div>\n          <div class=\"mod-roles\"><span class=\"badge b-mgr\"><span class=\"dot\">M</span></span><span class=\"badge b-hr\"><span class=\"dot\">H</span></span></div>\n          <p class=\"desc\">Manage job openings and the applications that come in through the public careers page.\n            Applicants apply online; you review them here and move them through your process.</p>\n          <ul>\n            <li>Post and edit openings; the public apply page collects candidate details and answers.</li>\n            <li>Review submitted applications and track candidates.</li>\n          </ul>\n        </div>\n\n        <div class=\"mod\">\n          <div class=\"mod-top\"><h3>Seminars &amp; Training</h3><span class=\"loc\">sidebar › Seminars &amp; Training</span></div>\n          <div class=\"mod-roles\">\n            <span class=\"badge b-mgr\"><span class=\"dot\">M</span></span>\n            <span class=\"badge b-hr\"><span class=\"dot\">H</span></span>\n            <span class=\"badge b-stf\"><span class=\"dot\">S</span> attend</span>\n          </div>\n          <p class=\"desc\">Create and run trainings and CPD seminars, and publish them to the public institute\n            page at <code>institute.sapphireclinicseast.org</code> where the public registers and pays.</p>\n          <ul>\n            <li>Create a seminar with schedule, speaker, CPD units, fee, and description.</li>\n            <li><b>Hide from public site:</b> tick this on a seminar to remove it from the public page entirely\n              while keeping all its records here.</li>\n            <li>Manage attendees, issue certificates, and generate posters and QR codes.</li>\n            <li>Staff see the trainings they're enrolled in and their certificates through their own account.</li>\n          </ul>\n        </div>\n\n        <div class=\"mod\">\n          <div class=\"mod-top\"><h3>Peer Evaluation</h3><span class=\"loc\">sidebar › Peer Evaluation</span></div>\n          <div class=\"mod-roles\"><span class=\"badge b-mgr\"><span class=\"dot\">M</span></span><span class=\"badge b-hr\"><span class=\"dot\">H</span></span><span class=\"badge b-stf\"><span class=\"dot\">S</span></span></div>\n          <p class=\"desc\">Structured peer feedback among staff, with separate clinical and administrative\n            evaluation forms. Staff complete evaluations of colleagues; HR reviews the results.</p>\n        </div>\n\n        <div class=\"mod\">\n          <div class=\"mod-top\"><h3>Manuals</h3><span class=\"loc\">sidebar › Manuals</span></div>\n          <div class=\"mod-roles\"><span class=\"badge b-mgr\"><span class=\"dot\">M</span></span><span class=\"badge b-hr\"><span class=\"dot\">H</span></span><span class=\"badge b-stf\"><span class=\"dot\">S</span></span></div>\n          <p class=\"desc\">The library of HR manuals and policies. Anyone signed in can open and read a manual —\n            this is the go-to reference for \"how do we do X here?\"</p>\n        </div>\n\n        <div class=\"mod\">\n          <div class=\"mod-top\"><h3>Templates</h3><span class=\"loc\">sidebar › Templates</span></div>\n          <div class=\"mod-roles\"><span class=\"badge b-mgr\"><span class=\"dot\">M</span></span><span class=\"badge b-hr\"><span class=\"dot\">H</span></span></div>\n          <p class=\"desc\">A catalog of reusable document templates (letters, forms, certificates) HR can pull\n            from instead of recreating documents each time.</p>\n        </div>\n      </div>\n\n      <!-- Everyday operations -->\n      <div class=\"grouphead\" id=\"g-ops\">Everyday operations</div>\n      <div class=\"cards\">\n\n        <div class=\"mod\">\n          <div class=\"mod-top\"><h3>Meetings</h3><span class=\"loc\">sidebar › Meetings</span></div>\n          <div class=\"mod-roles\"><span class=\"badge b-mgr\"><span class=\"dot\">M</span></span><span class=\"badge b-hr\"><span class=\"dot\">H</span></span><span class=\"badge b-stf\"><span class=\"dot\">S</span> invited</span></div>\n          <p class=\"desc\">Schedule meetings with timezone-aware times that sync automatically to Google Calendar.\n            Invited staff see the meetings they're part of.</p>\n          <ul>\n            <li>Set date, time, and timezone; the invite goes on the calendar automatically.</li>\n            <li>Staff see only the meetings they've been invited to.</li>\n          </ul>\n        </div>\n\n        <div class=\"mod\">\n          <div class=\"mod-top\"><h3>Task Checklist</h3><span class=\"loc\">sidebar › Task Checklist</span></div>\n          <div class=\"mod-roles\"><span class=\"badge b-mgr\"><span class=\"dot\">M</span></span><span class=\"badge b-hr\"><span class=\"dot\">H</span></span></div>\n          <p class=\"desc\">Assign and track HR tasks and to-dos, scoped to your branch. Good for onboarding steps,\n            recurring checklists, and follow-ups.</p>\n        </div>\n\n        <div class=\"mod\">\n          <div class=\"mod-top\"><h3>Weekly Accomplishment</h3><span class=\"loc\">sidebar › Weekly Accomplishment</span></div>\n          <div class=\"mod-roles\"><span class=\"badge b-mgr\"><span class=\"dot\">M</span></span><span class=\"badge b-hr\"><span class=\"dot\">H</span></span><span class=\"badge b-stf\"><span class=\"dot\">S</span> submit</span></div>\n          <p class=\"desc\">Staff log what they accomplished each week; HR and managers review the submissions.\n            The regular pulse of what everyone is working on.</p>\n        </div>\n\n        <div class=\"mod\">\n          <div class=\"mod-top\"><h3>Service Invoices</h3><span class=\"loc\">sidebar › Service Invoices</span></div>\n          <div class=\"mod-roles\"><span class=\"badge b-mgr\"><span class=\"dot\">M</span></span><span class=\"badge b-hr\"><span class=\"dot\">H</span></span><span class=\"badge b-stf\"><span class=\"dot\">S</span> consultants</span></div>\n          <p class=\"desc\">Monthly service invoices from consultants, tracked per branch. HR sees who has and\n            hasn't submitted for the month and can send reminders.</p>\n          <ul>\n            <li>Each consultant-branch has its own invoice row for the month.</li>\n            <li>Upload or mark submissions; chase the outstanding ones.</li>\n          </ul>\n          <div class=\"note\"><b>Deadline:</b> service invoices are due the <b>5th of every month</b>. The\n            notification bell flags the deadline so nothing slips.</div>\n        </div>\n\n        <div class=\"mod\">\n          <div class=\"mod-top\"><h3>Forms</h3><span class=\"loc\">sidebar › Forms</span></div>\n          <div class=\"mod-roles\"><span class=\"badge b-mgr\"><span class=\"dot\">M</span></span><span class=\"badge b-hr\"><span class=\"dot\">H</span></span></div>\n          <p class=\"desc\">Shareable questionnaires (registrations, reference checks, intake forms) with a public\n            link people fill in. Responses collect here, each downloadable as a PDF.</p>\n          <ul>\n            <li>Share a form's public link; submissions arrive in its Responses tab.</li>\n            <li>New responses trigger the notification bell and deep-link to that form.</li>\n            <li>Download any response as a PDF, or delete it.</li>\n          </ul>\n        </div>\n      </div>\n\n      <!-- Patient care & quality -->\n      <div class=\"grouphead\" id=\"g-care\">Patient care &amp; quality</div>\n      <div class=\"cards\">\n\n        <div class=\"mod\">\n          <div class=\"mod-top\"><h3>Patient CRM</h3><span class=\"loc\">sidebar › Patient CRM</span></div>\n          <div class=\"mod-roles\"><span class=\"badge b-mgr\"><span class=\"dot\">M</span></span><span class=\"badge b-hr\"><span class=\"dot\">H</span></span></div>\n          <p class=\"desc\">The directory of patients and their relationship with the clinic — used to look up a\n            patient and see their history and touchpoints.</p>\n        </div>\n\n        <div class=\"mod\">\n          <div class=\"mod-top\"><h3>Customer Survey</h3><span class=\"loc\">sidebar › Customer Survey</span></div>\n          <div class=\"mod-roles\"><span class=\"badge b-mgr\"><span class=\"dot\">M</span></span><span class=\"badge b-hr\"><span class=\"dot\">H</span></span></div>\n          <p class=\"desc\">Patient satisfaction surveys, typically collected via a QR code at the front desk.\n            Review scores and feedback to track service quality.</p>\n        </div>\n\n        <div class=\"mod\">\n          <div class=\"mod-top\"><h3>Patient Complaints</h3><span class=\"loc\">sidebar › Patient Complaints</span></div>\n          <div class=\"mod-roles\"><span class=\"badge b-mgr\"><span class=\"dot\">M</span></span><span class=\"badge b-hr\"><span class=\"dot\">H</span></span></div>\n          <p class=\"desc\">Log and track complaints raised by patients so each one is recorded, assigned, and\n            resolved rather than lost. New complaints show up on the notification bell.</p>\n        </div>\n\n        <div class=\"mod\">\n          <div class=\"mod-top\"><h3>Staff Concerns</h3><span class=\"loc\">sidebar › Staff Concerns</span></div>\n          <div class=\"mod-roles\"><span class=\"badge b-mgr\"><span class=\"dot\">M</span></span><span class=\"badge b-hr\"><span class=\"dot\">H</span></span></div>\n          <p class=\"desc\">The channel for concerns raised by staff. HR reviews and acts on them; new concerns\n            are flagged on the notification bell so they're seen promptly.</p>\n        </div>\n      </div>\n\n      <!-- Compliance & governance -->\n      <div class=\"grouphead\" id=\"g-gov\">Compliance &amp; governance</div>\n      <div class=\"cards\">\n\n        <div class=\"mod\">\n          <div class=\"mod-top\"><h3>Government Submissions</h3><span class=\"loc\">sidebar › Government Submissions</span></div>\n          <div class=\"mod-roles\"><span class=\"badge b-mgr\"><span class=\"dot\">M</span></span><span class=\"badge b-hr\"><span class=\"dot\">H</span></span></div>\n          <p class=\"desc\">Track statutory and government filings so compliance deadlines and submissions are in\n            one place rather than scattered across spreadsheets.</p>\n        </div>\n\n        <div class=\"mod\">\n          <div class=\"mod-top\"><h3>Document Hub</h3><span class=\"loc\">sidebar › Document Hub</span></div>\n          <div class=\"mod-roles\"><span class=\"badge b-mgr\"><span class=\"dot\">M</span></span><span class=\"badge b-hr\"><span class=\"dot\">H</span></span></div>\n          <p class=\"desc\">Central storage for shared HR and company documents — the shelf everyone in HR pulls\n            official files from.</p>\n        </div>\n\n        <div class=\"mod\">\n          <div class=\"mod-top\"><h3>KPI Monitoring</h3><span class=\"loc\">sidebar › KPI Monitoring</span></div>\n          <div class=\"mod-roles\"><span class=\"badge b-mgr\"><span class=\"dot\">M</span></span><span class=\"badge b-hr\"><span class=\"dot\">H</span></span></div>\n          <p class=\"desc\">Dashboards for the metrics the clinic tracks, so performance against targets is visible\n            at a glance.</p>\n        </div>\n\n        <div class=\"mod\">\n          <div class=\"mod-top\"><h3>Shareholders</h3><span class=\"loc\">sidebar › Shareholders</span></div>\n          <div class=\"mod-roles\"><span class=\"badge b-mgr\"><span class=\"dot\">M</span> Manager &amp; Director only</span></div>\n          <p class=\"desc\">Company equity records — common and preferred shares, share certificates, voting, and\n            board documents. Because it's sensitive ownership data, only the Manager and Directors can open it.</p>\n        </div>\n      </div>\n    </section>\n\n    <!-- ════ 4 · PLAYBOOKS ════ -->\n    <section id=\"play\">\n      <p class=\"eyebrow\">Section 4</p>\n      <h2>Role playbooks</h2>\n      <p>The most common jobs for each role, start to finish.</p>\n\n      <div class=\"play mgr\">\n        <h3><span class=\"badge b-mgr\"><span class=\"dot\">M</span> Clinic Manager</span></h3>\n        <ol>\n          <li><b>Onboard a new HR officer:</b> in <b>Access</b>, create their login and give them the\n            branch-admin role for their branch. They'll immediately see only that branch.</li>\n          <li><b>Add a new hire's record:</b> in <b>Staff Profiles</b> › New Staff, tick their branch(es) and\n            fill Employment Details for each.</li>\n          <li><b>Check the whole organization:</b> use the <b>Staff Dashboard</b> and <b>KPI Monitoring</b>\n            for cross-branch numbers.</li>\n          <li><b>Review governance:</b> open <b>Shareholders</b> for equity and board records — yours alone\n            (with Directors) to see.</li>\n          <li><b>Stay on top of exceptions:</b> watch the <b>notification bell</b> for concerns, complaints,\n            form responses, and the monthly invoice deadline across every branch.</li>\n        </ol>\n      </div>\n\n      <div class=\"play hr\">\n        <h3><span class=\"badge b-hr\"><span class=\"dot\">H</span> HR Officer</span></h3>\n        <ol>\n          <li><b>Keep records current:</b> in <b>Staff Profiles</b>, add and update your branch's people —\n            details, photos, and 201 files. You'll only ever see your branch's data.</li>\n          <li><b>Run the monthly invoice cycle:</b> in <b>Service Invoices</b>, track who has submitted, upload\n            invoices, and send reminders before the <b>5th</b>.</li>\n          <li><b>Handle what comes in:</b> clear the <b>notification bell</b> — respond to <b>Staff Concerns</b>\n            and <b>Patient Complaints</b>, and review new <b>Forms</b> responses.</li>\n          <li><b>Move hiring forward:</b> post openings and review applicants in <b>Hiring</b>.</li>\n          <li><b>Support development:</b> enroll staff in <b>Seminars &amp; Training</b>, schedule\n            <b>Meetings</b>, and review <b>Weekly Accomplishment</b> and <b>Peer Evaluation</b> submissions.</li>\n        </ol>\n      </div>\n\n      <div class=\"play stf\">\n        <h3><span class=\"badge b-stf\"><span class=\"dot\">S</span> Regular Staff</span></h3>\n        <ol>\n          <li><b>Check your profile:</b> open <b>Staff Profiles</b> to see your own record; tell HR if anything\n            is out of date.</li>\n          <li><b>Submit your week:</b> log your work in <b>Weekly Accomplishment</b>.</li>\n          <li><b>Grow:</b> attend the trainings you're enrolled in under <b>Seminars &amp; Training</b> and\n            download your certificates.</li>\n          <li><b>Show up prepared:</b> find the meetings you're invited to in <b>Meetings</b>.</li>\n          <li><b>Give feedback &amp; read up:</b> complete assigned <b>Peer Evaluations</b>, and use\n            <b>Manuals</b> whenever you need to check a policy.</li>\n        </ol>\n      </div>\n    </section>\n\n    <!-- ════ 5 · RULES ════ -->\n    <section id=\"rules\">\n      <p class=\"eyebrow\">Section 5</p>\n      <h2>Golden rules</h2>\n\n      <div class=\"call rule\"><span class=\"lbl\">Branch privacy</span>\n        An HR officer's view stops at their branch line. If you manage East, you will not see Greenhills'\n        people or the Greenhills half of a shared consultant — and vice versa. That's by design; ask a\n        Manager if you genuinely need cross-branch information.</div>\n\n      <div class=\"call rule\"><span class=\"lbl\">The 5th of the month</span>\n        Consultant service invoices are due the 5th. The notification bell reminds you, but build the habit\n        of clearing <b>Service Invoices</b> in the first week of each month.</div>\n\n      <div class=\"call rule\"><span class=\"lbl\">Sensitive data</span>\n        Government IDs, bank details, rates, and shareholder records are restricted. Staff never see\n        colleagues' financial or ID data; only Managers and Directors open Shareholders. Don't work around\n        these limits — they protect people.</div>\n\n      <div class=\"call tip\"><span class=\"lbl\">Let the bell drive your day</span>\n        For HR officers and managers, the notification bell is the shortest path to \"what needs me right now.\"\n        Start there: new concerns, complaints, and form responses all surface in one place and link straight\n        to the item.</div>\n\n      <div class=\"call tip\"><span class=\"lbl\">If a screen looks empty</span>\n        A short sidebar or a blank list usually means your role is correctly scoped — not that something broke.\n        If you truly can't reach something you need, that's an access question for your Manager, who can adjust\n        your role in <b>Access</b>.</div>\n    </section>\n\n  </div><!-- /content -->\n</div><!-- /shell -->\n</main>\n\n<footer>\n  <div class=\"wrap\">\n    <span>Aura Health Rehab · HR Portal Handbook</span>\n    <span>hr.sapphireclinicseast.org · Sapphire Clinics East Inc.</span>\n  </div>\n</footer>\n</body>\n</html>"
